<template>
  <div ref="root" class="traffic-select" @focusout="onFocusOut">
    <span :id="`${id}-label`" class="traffic-select-label">{{ label }}</span>
    <button ref="trigger" class="traffic-select-trigger" type="button" aria-haspopup="listbox"
      :aria-expanded="open" :aria-controls="id" :aria-labelledby="`${id}-label ${id}-value`"
      data-press-intent="custom" @click="toggle" @keydown="onTriggerKey">
      <span :id="`${id}-value`">{{ active.label }}</span>
      <svg viewBox="0 0 16 16" aria-hidden="true" :class="{turned:open}"><path d="m4 6 4 4 4-4"/></svg>
    </button>
    <Transition name="traffic-select">
      <div v-if="open" :id="id" ref="menu" class="traffic-select-menu" :class="{'opens-up':opensUp}"
        :style="{'--select-space':`${availableSpace}px`}" role="listbox" :aria-label="label" @keydown="onMenuKey">
        <button v-for="(option,index) in options" :key="option.value" type="button" role="option"
          :aria-selected="value===option.value" :tabindex="focused===index?0:-1" data-press-intent="custom"
          @focus="focused=index" @click="choose(option.value)">
          <span>{{ option.label }}</span><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3 8 3 3 7-7"/></svg>
        </button>
      </div>
    </Transition>
  </div>
</template>
<script setup>
/* global defineProps, defineEmits */
import {computed,ref,nextTick,onMounted,onBeforeUnmount,getCurrentInstance} from 'vue';
const props=defineProps({label:{type:String,required:true},value:{type:String,default:''},options:{type:Array,required:true}});
const emit=defineEmits(['select']);
const id=`traffic-options-${getCurrentInstance().uid}`;
const root=ref(null),trigger=ref(null),menu=ref(null),open=ref(false),focused=ref(0),opensUp=ref(false),availableSpace=ref(300);
const active=computed(()=>props.options.find(option=>option.value===props.value)||props.options[0]);
let typeAhead='',typeTimer;
async function show(){const rect=trigger.value.getBoundingClientRect(),below=window.innerHeight-rect.bottom-16,above=rect.top-84;opensUp.value=below<260&&above>below;availableSpace.value=Math.max(100,opensUp.value?above:below);focused.value=Math.max(0,props.options.findIndex(option=>option.value===props.value));open.value=true;await nextTick();focusOption(focused.value);}
function close(restore=false){open.value=false;if(restore)trigger.value?.focus({preventScroll:true});}
function toggle(){if(open.value)close(true);else show();}
function choose(value){emit('select',value);close(true);}
function focusOption(index){focused.value=Math.max(0,Math.min(props.options.length-1,index));const option=menu.value?.querySelectorAll('[role=option]')[focused.value];option?.focus({preventScroll:true});option?.scrollIntoView({block:'nearest'});}
function onTriggerKey(event){if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();show();}else if(event.key==='Escape')close();}
function onMenuKey(event){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true);return;}if(event.key==='Tab'){close();return;}const step={ArrowDown:1,ArrowUp:-1}[event.key];let index=step==null?null:focused.value+step;if(event.key==='Home')index=0;if(event.key==='End')index=props.options.length-1;if(index!==null){event.preventDefault();focusOption(index);}else if(event.key.length===1&&/\S/.test(event.key)){clearTimeout(typeTimer);typeAhead+=event.key.toLowerCase();typeTimer=setTimeout(()=>{typeAhead='';},500);const match=props.options.findIndex(option=>option.label.toLowerCase().startsWith(typeAhead));if(match>=0){event.preventDefault();focusOption(match);}}}
function outside(event){if(open.value&&!root.value?.contains(event.target))close();}
function onFocusOut(event){if(event.relatedTarget&&!root.value?.contains(event.relatedTarget))close();}
function resize(){close();}
onMounted(()=>{document.addEventListener('pointerdown',outside,true);window.addEventListener('resize',resize);});
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outside,true);window.removeEventListener('resize',resize);clearTimeout(typeTimer);});
</script>
<style scoped>
.traffic-select{position:relative;min-width:0}.traffic-select-label{display:block;margin-bottom:.45rem;font-size:.7rem;color:var(--traffic-muted)}
.traffic-select .traffic-select-trigger{display:flex;align-items:center;justify-content:space-between;gap:.8rem;box-sizing:border-box;width:100%;min-height:42px;padding:.55rem .7rem!important;border:1px solid var(--traffic-line)!important;border-radius:4px;background:var(--traffic-panel);font-size:.8rem;user-select:none}
.traffic-select-trigger>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.traffic-select-trigger svg{width:14px;height:14px;flex:none;fill:none;stroke:currentColor;stroke-width:1.2;transition:transform 140ms}.traffic-select-trigger svg.turned{transform:rotate(180deg)}
.traffic-select-menu{position:absolute;z-index:6;box-sizing:border-box;inset:calc(100% + 6px) 0 auto;padding:5px;max-height:min(320px,var(--select-space));overflow:auto;overscroll-behavior:contain;border:1px solid var(--traffic-line);border-radius:5px;background:var(--traffic-panel);box-shadow:0 6px 18px rgb(0 0 0/.07)}
.traffic-select-menu.opens-up{inset:auto 0 calc(100% - 18px)}.traffic-select-menu button{box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;gap:.5rem;width:100%;min-height:38px;padding:.5rem .6rem!important;border-radius:3px;font-size:.8rem;text-align:left}
.traffic-select-menu button[aria-selected=true]{background:var(--traffic-wash)}.traffic-select-menu svg{width:12px;height:12px;flex:none;fill:none;stroke:var(--traffic-accent);stroke-width:1.3;opacity:0}.traffic-select-menu [aria-selected=true] svg{opacity:1}.traffic-select-menu button:focus-visible{outline:1px solid var(--traffic-accent);outline-offset:-2px}
.traffic-select-enter-active,.traffic-select-leave-active{transition:opacity 110ms ease,transform 110ms ease}.traffic-select-enter-from,.traffic-select-leave-to{opacity:0;transform:translateY(-3px)}
@media(prefers-reduced-motion:reduce){.traffic-select-trigger svg,.traffic-select-enter-active,.traffic-select-leave-active{transition:none}}
</style>
